function PVPArenaReplayTitleGroup:RefreshUI(oneMatchChartData)
    local leftPlayerId        = oneMatchChartData.leftPlayerId
    local leftInfo            = oneMatchChartData.leftInfo
    self:RefreshHeadNode(self.LeftHead.gameObject, leftInfo, leftPlayerId)

    local rightPlayerId       = oneMatchChartData.rightPlayerId
