    self.ScoreTextL.text = tostring(oneMatchChartData.leftScore)
    self.ScoreTextR.text = tostring(oneMatchChartData.rightScore)

end

function PVPArenaReplayTitleGroup:RefreshHeadNode(gameObject, info, playerId)
    ---@type PVPArenaBasePlayerInfo
    local env = CfUtils.GetLuaScr(gameObject, PVPArenaBasePlayerInfoPath)
    if isNull(env) then return end
    env:RefreshUI(info, playerId)
end

